// @minecraft/server 1.14.0 TAKLIDI — main.js'i Minecraft olmadan CALISTIRMAK icin.
//
// Neden: check_pack.py kimlikleri dogruluyor, node --check sozdizimini. Ikisi de
// kodu CALISTIRMIYOR. Paketin 4000 satirlik betigi bugune kadar yalnizca oyunda
// kosmustu; modul yuklenirken atilan tek bir TypeError butun paketi sessizce
// oldurur (yasanmis: world.beforeEvents.entityHurt 1.x'te yok, o satirdan
// sonrasi HIC kaydolmamisti).
//
// Taklit, davranisi TEMSIL EDECEK kadar gercek: patlama gercekten hasar verir,
// direnc hasari azaltir, getBlock cagrilari sayilir (tick butcesi olculebilsin),
// applyKnockback'in NESNE bicimi 1.14'te oldugu gibi HATA FIRLATIR.
const AIR = "minecraft:air";

let nextId = 1;
const state = {
  tick: 0,
  absoluteTime: 100000,          // dunya saati: "yeniden yukleme"de KORUNUR
  blocks: new Map(),             // "dim|x,y,z" -> typeId
  entities: [],
  worldProps: new Map(),
  jobs: new Map(),               // handle -> {cb, every, next, timeout}
  nextJob: 1,
  log: { particles: [], sounds: [], explosions: [], commands: [], actionBars: [], items: [], timeSets: [], weather: [] },
  counters: { getBlock: 0, getBlockThisTick: 0, maxGetBlockPerTick: 0 },
  ground: 63,                    // y <= ground -> tas, ustu hava
  viewBlock: null,               // getBlockFromViewDirection sonucu
  viewEntities: [],
};

const bkey = (d, x, y, z) => `${d}|${Math.floor(x)},${Math.floor(y)},${Math.floor(z)}`;

function blockAt(dimId, x, y, z) {
  const k = bkey(dimId, x, y, z);
  if (state.blocks.has(k)) return state.blocks.get(k);
  return Math.floor(y) <= state.ground ? "minecraft:stone" : AIR;
}

class Block {
  constructor(dim, x, y, z) {
    this.dimension = dim;
    this.location = { x: Math.floor(x), y: Math.floor(y), z: Math.floor(z) };
  }
  get typeId() { return blockAt(this.dimension.id, this.location.x, this.location.y, this.location.z); }
  setType(id) {
    const t = typeof id === "string" ? id : (id && id.__id);
    if (typeof t !== "string") throw new TypeError("setType: gecersiz blok kimligi");
    state.blocks.set(bkey(this.dimension.id, this.location.x, this.location.y, this.location.z), t);
  }
  setPermutation(p) {
    if (!p || !p.__id) throw new TypeError("setPermutation: gecersiz permutation");
    this.setType(p.__id);
  }
  getRedstonePower() { return this.__redstone || 0; }
  get permutation() { return { type: { id: this.typeId } }; }
}

class Entity {
  constructor(typeId, dimension, location) {
    this.typeId = typeId;
    this.id = String(nextId++);
    this.dimension = dimension;
    this.location = { ...location };
    this.nameTag = "";
    this.isSneaking = false;
    this.effects = new Map();
    this.props = new Map();
    this.dynamic = new Map();
    this.maxHealth = 20;
    this.health = 20;
    this.dead = false;
    this.knockbacks = [];
    this.impulses = [];
    this.damages = [];
    // Vurusun SEBEBI de kaydedilir. Sahte createExplosion her patlamada
    // hasar veriyor; sebep olmadan 'TNT etki uyguladi' ile 'sadece
    // patladi' ayirt edilemiyordu ve 6 TNT bos gecip testi geciyordu.
    this.hits = [];
    this.inv = new Array(36).fill(undefined);   // envanter yuvalari
    this.selectedSlotIndex = 0;
  }
  getComponent(name) {
    if (name === "minecraft:inventory") {
      // Gercek Bedrock'ta getItem bir KOPYA dondurur: yiginin amount'unu
      // degistirmek yeterli degildir, setItem ile geri yazmak gerekir. Taklit
      // de kopya dondurur, boylece "geri yazmayi unutma" hatasi burada yakalanir.
      const self = this;
      return {
        container: {
          get size() { return self.inv.length; },
          getItem: (i) => (self.inv[i]
            ? new ItemStack(self.inv[i].typeId, self.inv[i].amount) : undefined),
          setItem: (i, it) => { self.inv[i] = it ? new ItemStack(it.typeId, it.amount) : undefined; },
          addItem: (it) => {
            const k = self.inv.findIndex((s) => !s);
            if (k >= 0) self.inv[k] = new ItemStack(it.typeId, it.amount);
          },
        },
      };
    }
    if (name === "minecraft:equippable") {
      const self = this;
      return {
        getEquipment: (slot) => (slot === "Mainhand" && self.mainhand
          ? { typeId: self.mainhand } : undefined),
      };
    }
    if (name !== "minecraft:health") return undefined;
    const self = this;
    return {
      get currentValue() { return self.health; },
      setCurrentValue(v) { self.health = v; },
      resetToMaxValue() { self.health = self.maxHealth; },
    };
  }
  applyDamage(n, opts) {
    if (opts && opts.cause && typeof opts.cause !== "string") throw new TypeError("cause");
    // Direnc V'yi KOTUMSER modelle (%80): boylece testler yalniz direnc
    // sayesinde gecmez, ikinci katman (can geri koyma) da sinanir.
    const r = this.effects.get("resistance");
    const mult = r ? Math.max(0, 1 - Math.min(5, (r.amplifier + 1)) * 0.16) : 1;
    const dealt = n * mult;
    this.damages.push(dealt);
    this.hits.push({ amount: dealt, cause: (opts && opts.cause) || null });
    this.health -= dealt;
    if (this.health <= 0) { this.health = 0; this.dead = true; }
    return true;
  }
  applyKnockback(a, b, c, d) {
    // 1.14'te imza DORT SAYIDIR. Nesne bicimi 2.x'te geldi -> burada hata.
    if (typeof a === "object") throw new TypeError("applyKnockback: 1.14'te nesne bicimi yok");
    if ([a, b, c, d].some((v) => typeof v !== "number")) throw new TypeError("applyKnockback: dort sayi bekler");
    this.knockbacks.push([a, b, c, d]);
  }
  applyImpulse(v) {
    if (this.typeId === "minecraft:player") throw new TypeError("applyImpulse oyuncuda calismaz");
    this.impulses.push(v);
  }
  addEffect(id, dur, opts) {
    if (typeof id !== "string") throw new TypeError("addEffect: kimlik metin olmali");
    const amp = (opts && opts.amplifier) || 0;
    if (amp > 255) throw new RangeError("amplifier 255'i asamaz");
    if (id === "health_boost") { this.maxHealth = 20 + 4 * (amp + 1); }
    this.effects.set(id, { amplifier: amp, duration: dur });
  }
  removeEffect(id) { this.effects.delete(id); }
  getEffects() { return [...this.effects.entries()].map(([k, v]) => ({ typeId: k, ...v })); }
  getTags() { return this.tags || []; }
  addTag(t) { (this.tags = this.tags || []).push(t); }
  teleport(loc, opts) {
    this.location = { ...loc };
    if (opts && opts.dimension) this.dimension = opts.dimension;
  }
  getViewDirection() { return { x: 0, y: 0, z: 1 }; }
  // Comelince goz ALCALIR. Gercek deger surume gore oynar; onemli olan ikisinin
  // FARKLI olmasi, boylece "kamera comelmeyi izliyor mu" sinanabiliyor.
  getHeadLocation() {
    return { x: this.location.x, y: this.location.y + (this.isSneaking ? 1.26 : 1.62),
             z: this.location.z };
  }
  getBlockFromViewDirection() { return state.viewBlock; }
  getEntitiesFromViewDirection() { return state.viewEntities; }
  getProperty(n) { return this.props.has(n) ? this.props.get(n) : undefined; }
  triggerEvent(n) {
    const ev = (this.__events || {})[n];
    if (!ev) throw new Error(`triggerEvent: '${n}' diye bir olay yok`);
    if (ev.set_property) for (const [k, v] of Object.entries(ev.set_property)) this.props.set(k, v);
  }
  getDynamicProperty(k) { return this.dynamic.get(k); }
  setDynamicProperty(k, v) { if (v === undefined) this.dynamic.delete(k); else this.dynamic.set(k, v); }
  remove() { this.dead = true; state.entities = state.entities.filter((e) => e !== this); }
  runCommand(c) { state.log.commands.push({ id: this.id, c }); return { successCount: 1 }; }
  sendMessage(m) { state.log.actionBars.push({ id: this.id, msg: String(m) }); }
  getRotation() { return { x: 0, y: 0 }; }
}

class Player extends Entity {
  constructor(name, dimension, location) {
    super("minecraft:player", dimension, location);
    this.name = name;
    this.nameTag = name;
    this.onScreenDisplay = {
      setActionBar: (t) => state.log.actionBars.push({ id: this.id, msg: String(t) }),
    };
    // Kamera cagrilari KAYDEDILIR: POV kamerasinin nereye surulduugu ancak
    // boyle sinanabilir (goz yuksekligi, one oteleme, easing).
    this.cameraSets = [];
    this.cameraActive = null;
    this.camera = {
      setCamera: (preset, opts) => {
        if (typeof preset !== "string") throw new TypeError("setCamera: on-ayar adi metin olmali");
        this.cameraSets.push({ preset, opts });
        this.cameraActive = preset;
      },
      clear: () => { this.cameraSets.push({ preset: null }); this.cameraActive = null; },
    };
  }
}

class Dimension {
  constructor(id) { this.id = id; }
  getBlock(loc) {
    if (!loc || typeof loc.x !== "number") return undefined;
    state.counters.getBlock++;
    state.counters.getBlockThisTick++;
    if (loc.y < -64 || loc.y > 320) return undefined;
    return new Block(this, loc.x, loc.y, loc.z);
  }
  getEntities(opts) {
    let out = state.entities.filter((e) => e.dimension.id === this.id && !e.dead);
    if (opts && opts.location && typeof opts.maxDistance === "number") {
      out = out.filter((e) => dist(e.location, opts.location) <= opts.maxDistance);
    }
    if (opts && opts.excludeTypes) out = out.filter((e) => !opts.excludeTypes.includes(e.typeId));
    return out;
  }
  getPlayers(opts) { return this.getEntities(opts).filter((e) => e.typeId === "minecraft:player"); }
  createExplosion(loc, power, opts) {
    state.log.explosions.push({ loc: { ...loc }, power, opts: opts || {} });
    const R = power * 2;
    for (const e of this.getEntities({ location: loc, maxDistance: R })) {
      const d = dist(e.location, loc);
      const dmg = Math.max(0, (1 - d / R)) * power * 7;   // yakin mesafe olduruculugu
      if (dmg > 0) e.applyDamage(dmg, { cause: "entityExplosion" });
    }
    return true;
  }
  spawnEntity(typeId, loc) {
    if (typeof typeId !== "string") throw new TypeError("spawnEntity: kimlik metin olmali");
    const e = new Entity(typeId, this, loc);
    state.entities.push(e);
    return e;
  }
  spawnItem(stack, loc) { state.log.items.push({ stack, loc }); return new Entity("minecraft:item", this, loc); }
  spawnParticle(id, loc) {
    if (typeof id !== "string") throw new TypeError("spawnParticle: kimlik metin olmali");
    state.log.particles.push(id);
  }
  playSound(id, loc, o) {
    if (typeof id !== "string") throw new TypeError("playSound: kimlik metin olmali");
    state.log.sounds.push(id);
  }
  // Hava olayi tum dunyayi etkiler; suresini test edebilmek icin kaydediyoruz.
  setWeather(type, ticks) {
    if (typeof type !== "string") throw new TypeError("setWeather: tur metin olmali");
    state.log.weather.push({ type, ticks });
  }
}

function dist(a, b) {
  const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

const dims = new Map([
  ["minecraft:overworld", new Dimension("minecraft:overworld")],
  ["minecraft:nether", new Dimension("minecraft:nether")],
  ["minecraft:the_end", new Dimension("minecraft:the_end")],
]);

function evbus() {
  const subs = [];
  return { subscribe: (f) => { subs.push(f); return f; }, unsubscribe: () => {}, __subs: subs };
}

const AFTER = ["itemUse", "itemCompleteUse", "playerPlaceBlock", "playerBreakBlock",
  "playerSpawn", "worldLoad", "entityHurt", "entityHitEntity", "playerInteractWithBlock"];
const BEFORE = ["explosion", "playerInteractWithEntity", "playerInteractWithBlock"];

const world = {
  afterEvents: Object.fromEntries(AFTER.map((n) => [n, evbus()])),
  beforeEvents: Object.fromEntries(BEFORE.map((n) => [n, evbus()])),
  getDimension: (id) => {
    const d = dims.get(id);
    if (!d) throw new Error(`getDimension: '${id}' yok`);
    return d;
  },
  getPlayers: (opts) => dims.get("minecraft:overworld").getPlayers(opts)
    .concat(dims.get("minecraft:nether").getPlayers(opts))
    .concat(dims.get("minecraft:the_end").getPlayers(opts)),
  getDynamicProperty: (k) => state.worldProps.get(k),
  setDynamicProperty: (k, v) => { if (v === undefined) state.worldProps.delete(k); else state.worldProps.set(k, v); },
  getAbsoluteTime: () => state.absoluteTime,
  // Gunun saati GERCEKTEN degissin: "Gunes TNT gece calisiyor mu" ancak
  // set edilen degeri gorerek sinanabilir.
  getTimeOfDay: () => (state.timeOfDay !== undefined ? state.timeOfDay : state.absoluteTime % 24000),
  setTimeOfDay: (t) => { state.timeOfDay = t; state.log.timeSets.push(t); },
};

const system = {
  get currentTick() { return state.tick; },
  run(cb) { state.jobs.set(state.nextJob, { cb, timeout: true, next: state.tick }); return state.nextJob++; },
  runTimeout(cb, delay) {
    state.jobs.set(state.nextJob, { cb, timeout: true, next: state.tick + (delay || 0) });
    return state.nextJob++;
  },
  runInterval(cb, every) {
    const e = Math.max(1, every || 1);
    state.jobs.set(state.nextJob, { cb, every: e, next: state.tick + e });
    return state.nextJob++;
  },
  clearRun(h) { state.jobs.delete(h); },
};

class BlockPermutation {
  static resolve(id, states) {
    if (typeof id !== "string") throw new TypeError("resolve: kimlik metin olmali");
    return { __id: id, __states: states || {} };
  }
}
class ItemStack {
  constructor(typeId, amount) { this.typeId = typeId; this.amount = amount || 1; }
}
const EquipmentSlot = { Head: "Head", Chest: "Chest", Legs: "Legs", Feet: "Feet", Mainhand: "Mainhand" };

// ---- test kontrol yuzeyi
const __sim = {
  state, Entity, Player, Block, dist,
  dim: (id = "minecraft:overworld") => dims.get(id),
  // Bedrock'ta oyuncu cikinca elde tutulan varlik referansi GECERSIZLESIR ve
  // uzerindeki her okuma InvalidEntityError firlatir. Bir runInterval'in
  // icinden kacan bu istisna donguyu kalici durdurur, ozellik sessizce olur.
  // Testler bu senaryoyu ancak boyle kurabilir.
  gecersizKil(e) {
    const saklanan = { id: e.id, location: e.location, dimension: e.dimension, name: e.name };
    e.__saklanan = saklanan;
    for (const k of ["id", "location", "dimension", "name"]) {
      Object.defineProperty(e, k, {
        configurable: true,
        get() { throw new Error("InvalidEntityError: player has left"); },
        set() {},
      });
    }
    e.dead = true;
    const i = state.entities.indexOf(e);
    if (i >= 0) state.entities.splice(i, 1);
  },
  // Ayni kimlikle geri giren oyuncu: kalici kilitlenmeleri sinamanin yolu.
  geriGetir(e) {
    const v = e.__saklanan;
    if (!v) return e;
    for (const k of ["id", "location", "dimension", "name"]) {
      Object.defineProperty(e, k, { configurable: true, writable: true, value: v[k] });
    }
    e.dead = false;
    if (!state.entities.includes(e)) state.entities.push(e);
    return e;
  },
  addPlayer(name, loc = { x: 0, y: 64, z: 0 }, dimId = "minecraft:overworld") {
    const p = new Player(name, dims.get(dimId), loc);
    state.entities.push(p);
    return p;
  },
  addMob(typeId, loc = { x: 2, y: 64, z: 0 }, dimId = "minecraft:overworld") {
    const e = new Entity(typeId, dims.get(dimId), loc);
    state.entities.push(e);
    return e;
  },
  setBlock(dimId, x, y, z, id) { state.blocks.set(bkey(dimId, x, y, z), id); },
  tick(n = 1) {
    for (let i = 0; i < n; i++) {
      state.tick++;
      state.absoluteTime++;
      state.counters.getBlockThisTick = 0;
      for (const [h, j] of [...state.jobs]) {
        if (j.next > state.tick) continue;
        if (j.timeout) state.jobs.delete(h); else j.next = state.tick + j.every;
        try { j.cb(); } catch (e) { __sim.errors.push(`tick ${state.tick}: ${e && e.stack || e}`); }
      }
      if (state.counters.getBlockThisTick > state.counters.maxGetBlockPerTick) {
        state.counters.maxGetBlockPerTick = state.counters.getBlockThisTick;
      }
    }
  },
  fire(kind, name, ev) {
    const bus = (kind === "before" ? world.beforeEvents : world.afterEvents)[name];
    if (!bus) throw new Error(`olay yok: ${kind}.${name}`);
    for (const f of bus.__subs) f(ev);
  },
  subCount(kind, name) {
    const bus = (kind === "before" ? world.beforeEvents : world.afterEvents)[name];
    return bus ? bus.__subs.length : 0;
  },
  jobCount() { return state.jobs.size; },
  errors: [],
  reload() {
    // Dunya yeniden yuklenmesi: tick sayaci SIFIRLANIR, dunya saati ve kalici
    // ozellikler KORUNUR. system.currentTick'e yazilan zaman damgalarini
    // yakalayan senaryo budur.
    //
    // ISLER TEMIZLENMEZ. Bir kere temizlenmisti ve main.js'in KALICI donguleri
    // (morph yetenekleri, ipucu cubugu, sinirsiz can tazelemesi, redstone
    // taramasi) o noktadan sonra bir daha kosmadi: reload'dan SONRAKI her
    // senaryo sessizce bos gecti. Gercek dunyada betik yeniden yuklenir ve
    // dongulerini yeniden kurar; burada modulu yeniden yukleyemedigimiz icin
    // dogru taklit, dongulerin AYAKTA kalmasi.
    state.tick = 0;
    // Sayaci sifirlarken bekleyen isleri de yeni tabana tasi. Tasimazsak
    // hepsinin "next" degeri binlerde kalir ve reload'dan sonra HICBIRI
    // kosmaz — yine sessiz bir bos gecis.
    for (const j of state.jobs.values()) j.next = state.tick + (j.every || 0);
  },
  reset() {
    state.blocks.clear();
    state.entities = [];
    state.log = { particles: [], sounds: [], explosions: [], commands: [], actionBars: [], items: [], timeSets: [], weather: [] };
    state.timeOfDay = undefined;
    state.counters.getBlockThisTick = 0;
    state.counters.maxGetBlockPerTick = 0;
    state.viewBlock = null;
    state.viewEntities = [];
    __sim.errors.length = 0;
  },
};

export { world, system, BlockPermutation, ItemStack, EquipmentSlot, __sim };
